72		// 以及当时的报价和持仓限额快照；不得产生修改成功或撤销记录。
73		recs := e.Records()
74		if len(recs) != before+1 {
75			t.Fatalf("只能追加一条拒绝记录，实际新增 %d 条", len(recs)-before)
76		}
77		rj := recs[len(recs)-1]
78		if rj.Kind != RecordRejected {
79			t.Fatalf("新增记录必须是拒绝记录: %+v", rj)
80		}
81		if rj.OrderID != target || rj.Qty != 4 || rj.Limit != 1 {
82			t.Fatalf("拒绝记录须保留订单编号与申请总量/限价: %+v", rj)
83		}
84		if !strings.Contains(rj.Reason, "int64") {
85			t.Fatalf("拒绝原因须明确为 int64 溢出: %q", rj.Reason)
86		}
87		if !rj.QuoteValid || rj.QuoteSeq != 1 || rj.QuoteMoment != 1 || rj.QuotePrice != 1 {
88			t.Fatalf("拒绝记录缺少报价快照: %+v", rj)
89		}
90		if !rj.MaxPositionValid || rj.MaxPosition != M {
91			t.Fatalf("拒绝记录缺少最大持仓量快照: %+v", rj)
92		}
93		for _, r := range recs[before:] {
94			if r.Kind == RecordModified || r.Kind == RecordCanceled {
95				t.Fatalf("不得产生修改成功或撤销记录: %+v", r)
96			}
97		}
98	
99		// 被修改订单的总量、限价、已成交量和状态保持原值；另一笔买单仍然有效，
100		// 不能为了腾出额度撤销其他订单。
101		o, _ := e.Order(target)
102		if o.Qty != 2 || o.Limit != 1 || o.Filled != 1 || o.Status != StatusPartial || o.Remaining() != 1 {
103			t.Fatalf("溢出拒绝不得改变被修改订单: %+v", o)
104		}
105		if o, _ := e.Order(other); o.Status != StatusPending || o.Qty != 1 || o.Remaining() != 1 {
106			t.Fatalf("溢出拒绝不得影响另一笔有效买单: %+v", o)
107		}
108	
109		// 现金余额、占用现金、可用现金及合约持仓均与申请前一致：
110		// 不能先释放旧占用再留下不完整的结果。
111		if e.Cash() != 7 || e.ReservedCash() != 2 || e.AvailableCash() != 5 || e.Position("A") != M-3 {
112			t.Fatalf("溢出拒绝不得改变资金与持仓: cash=%d reserved=%d available=%d pos=%d",
113				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"))
114		}
115	}
116	
117	// TestModifyBuyPositionSumExactlyInt64Max 在相同持仓和订单条件下，把 target 总量
118	// 改为 3：新剩余量为 2，合约合计占用 (M-3)+1+2 恰好为 M，应成功替换占用并留下
119	// 修改记录；已成交的 1 份只计入持仓，不能再次计入未成交占用，历史成交金额保持不变。
120	func TestModifyBuyPositionSumExactlyInt64Max(t *testing.T) {
121		M := int64(math.MaxInt64)
122		e, _, target := setupModifyNearInt64Max(t)
123	
124		before := len(e.Records())
125		mustModify(t, e, target, 3, 1)
126	
127		// 恰好用满额度：成功替换占用，只追加一条修改记录。
128		recs := e.Records()
129		if len(recs) != before+1 || recs[len(recs)-1].Kind != RecordModified {
130			t.Fatalf("恰好用满额度的修改必须成功且只留一条修改记录，新增 %d 条", len(recs)-before)
131		}
132		r := recs[len(recs)-1]
133		if r.OrderID != target || r.OldQty != 2 || r.OldLimit != 1 || r.OldFilled != 1 ||
134			r.Qty != 3 || r.Limit != 1 || r.Filled != 1 || r.Remaining != 2 {
135			t.Fatalf("修改记录前后参数错误: %+v", r)
136		}
137		if !r.QuoteValid || r.QuoteSeq != 1 || r.QuotePrice != 1 ||
138			!r.MaxPositionValid || r.MaxPosition != M {
139			t.Fatalf("修改记录必须固化当时报价与限额: %+v", r)
140		}
141	
142		o, _ := e.Order(target)
143		if o.Qty != 3 || o.Limit != 1 || o.Filled != 1 || o.Status != StatusPartial || o.Remaining() != 2 {
144			t.Fatalf("修改后订单状态错误: %+v", o)
145		}
146	
147		// 已成交的 1 份只计入持仓：占用现金只按未成交剩余量计（other 1 + target 2 = 3），
148		// 历史成交金额保持不变（现金 7 不因修改重新计价）。
149		if e.Cash() != 7 || e.ReservedCash() != 3 || e.AvailableCash() != 4 || e.Position("A") != M-3 {
150			t.Fatalf("修改后资金与持仓错误: cash=%d reserved=%d available=%d pos=%d",
151				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"))
152		}
153	
154		// 合计恰好为 M：再申请 1 份即 M+1，必须按溢出拒绝（证明占用恰好用满且已成交
155		// 部分未被重复计入未成交占用，否则修改时的合计判断早已溢出）。
156		if _, err := e.Buy("A", 1, 1); !errors.Is(err, ErrInt64Overflow) {
157			t.Fatalf("合计恰好为 M 后再买 1 份应溢出拒绝，实际 %v", err)
158		}
159	
160		// 剩余部分仍可按新参数成交：成交 2 份 @1 后持仓 M-1、现金 5，历史成交不重新计价。
161		if _, err := e.Fill(Trade{TradeID: 4, OrderID: target, Symbol: "A", Side: Buy, Price: 1, Qty: 2}); err != nil {
162			t.Fatalf("修改后剩余部分应能按新参数成交: %v", err)
163		}
164		if e.Cash() != 5 || e.ReservedCash() != 1 || e.Position("A") != M-1 {
165			t.Fatalf("按新参数成交后账目错误: cash=%d reserved=%d pos=%d",
166				e.Cash(), e.ReservedCash(), e.Position("A"))
167		}
168		if o, _ := e.Order(target); o.Status != StatusFilled || o.Filled != 3 {
169			t.Fatalf("target 应全部成交: %+v", o)
170		}
171	}
172	
173	// TestModifyPendingBuyPositionSumOverflow 覆盖待成交买单（无成交）的同类数量溢出：
174	// 把待成交的 other（总量 1、剩余 1）改为总量 4 后，合约合计占用
175	// (M-3)+1(target 剩余)+4 = M+2 超出 int64，必须整体拒绝且保持全部状态。
176	func TestModifyPendingBuyPositionSumOverflow(t *testing.T) {
177		M := int64(math.MaxInt64)
178		e, other, target := setupModifyNearInt64Max(t)
179	
180		before := len(e.Records())
181		err := e.Modify(other, 4, 1)
182		if !errors.Is(err, ErrInt64Overflow) {
183			t.Fatalf("待成交买单合计 M+2 超出 int64 必须返回包装 ErrInt64Overflow 的错误，实际 %v", err)
184		}
185	
186		recs := e.Records()
187		if len(recs) != before+1 {
188			t.Fatalf("只能追加一条拒绝记录，实际新增 %d 条", len(recs)-before)
189		}
190		rj := recs[len(recs)-1]
191		if rj.Kind != RecordRejected || rj.OrderID != other || rj.Qty != 4 || rj.Limit != 1 ||
192			!strings.Contains(rj.Reason, "int64") {
193			t.Fatalf("拒绝记录要素错误: %+v", rj)
194		}
195		if !rj.QuoteValid || rj.QuotePrice != 1 || !rj.MaxPositionValid || rj.MaxPosition != M {
196			t.Fatalf("拒绝记录缺少报价与限额快照: %+v", rj)
197		}
198	
199		if o, _ := e.Order(other); o.Qty != 1 || o.Limit != 1 || o.Filled != 0 ||
200			o.Status != StatusPending || o.Remaining() != 1 {
201			t.Fatalf("溢出拒绝不得改变待成交订单: %+v", o)
202		}
203		if o, _ := e.Order(target); o.Qty != 2 || o.Filled != 1 || o.Status != StatusPartial {
204			t.Fatalf("溢出拒绝不得影响部分成交订单: %+v", o)
205		}
206		if e.Cash() != 7 || e.ReservedCash() != 2 || e.AvailableCash() != 5 || e.Position("A") != M-3 {
207			t.Fatalf("溢出拒绝不得改变资金与持仓: cash=%d reserved=%d available=%d pos=%d",
208				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"))
209		}
210	}
211	
212	// TestModifyPositionLimitRepresentableExcessKeepsOrdinaryRejection 保留合计可表示但
213	// 超过较小持仓限额时的普通拒绝：合计 6 可用 int64 表示但超过限额 5，须按原有
214	// “超过最大持仓量”原因拒绝，不得返回 ErrInt64Overflow；恰好等于限额仍允许。
215	func TestModifyPositionLimitRepresentableExcessKeepsOrdinaryRejection(t *testing.T) {
216		e, _ := NewEngine(1000)
217		mustSetMax(t, e, "B", 5)
218		mustQuote(t, e, "B", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
219		b1 := mustBuy(t, e, "B", 2, 10)
220		b2 := mustBuy(t, e, "B", 1, 10)
221		if _, err := e.Fill(Trade{TradeID: 1, OrderID: b1, Symbol: "B", Side: Buy, Price: 10, Qty: 1}); err != nil {
222			t.Fatal(err)
223		}
224		// 持仓 1，b1 剩余 1，b2 剩余 1，合计占用 3。
225	
226		before := len(e.Records())
227		err := e.Modify(b1, 5, 10) // 新剩余 4：1+1+4=6 可表示但超过限额 5
228		if err == nil {
229			t.Fatal("可表示但超限的修改必须拒绝")
230		}
231		if errors.Is(err, ErrInt64Overflow) {
232			t.Fatalf("合计可表示的普通超限不得返回 ErrInt64Overflow: %v", err)
233		}
234		expectErr(t, err, "超过最大持仓量")
235	
236		recs := e.Records()
237		if len(recs) != before+1 || recs[len(recs)-1].Kind != RecordRejected {
238			t.Fatal("普通超限只能追加一条拒绝记录")
239		}
240		if rj := recs[len(recs)-1]; !strings.Contains(rj.Reason, "超过最大持仓量") ||
241			rj.OrderID != b1 || rj.Qty != 5 || rj.Limit != 10 {
242			t.Fatalf("普通超限拒绝记录要素错误: %+v", rj)
243		}
244		if o, _ := e.Order(b1); o.Qty != 2 || o.Limit != 10 || o.Filled != 1 || o.Status != StatusPartial {
245			t.Fatalf("普通超限拒绝不得改变订单: %+v", o)
246		}
247		if o, _ := e.Order(b2); o.Status != StatusPending || o.Remaining() != 1 {
248			t.Fatalf("普通超限拒绝不得影响其他订单: %+v", o)
249		}
250	
251		// 恰好用满较小限额仍允许：新剩余 3，1+1+3=5。
252		mustModify(t, e, b1, 4, 10)
253		if o, _ := e.Order(b1); o.Qty != 4 || o.Remaining() != 3 {
254			t.Fatalf("恰好用满限额应成功: %+v", o)
255		}
256	}
