	}

	id := e.nextOrderID + 1
	e.nextOrderID = id
	o := &Order{
		ID:     id,
		Symbol: symbol,
		Side:   side,
		Limit:  limit,
		Qty:    qty,
		Status: StatusPending,
	}
	e.orders[id] = o

	if side == Buy {
		e.reservedCash += limit * qty
		st.reservedBuy += qty
		st.buyOrderIDs = append(st.buyOrderIDs, id)
	} else {
		st.reservedSell += qty
	}

	e.appendRecord(Record{
		Kind:      RecordAccepted,
		Symbol:    symbol,
		Side:      side,
		OrderID:   id,
		Limit:     limit,
		Qty:       qty,
		Filled:    0,
		Remaining: qty,
	}, st)
	return id, nil
}

